def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_threats = 0
    urgent_opponents = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_threats += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, max(1.0, DAILY_SALARY * 0.25)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if slots >= 2:
        danger -= 1
    if rich_threats >= 2 and slots == 1:
        danger += 1

    if hp <= 2 or no_water_days >= 2:
        bid = max(138.0, highest_prev + 2.0)
    elif danger >= 4:
        bid = max(132.0, avg_prev + 3.0)
    elif slots >= 2:
        if highest_prev >= 135:
            bid = 92.0
        else:
            bid = max(78.0, min(110.0, avg_prev * 0.72 + 8.0))
    else:
        if hp >= 7 and no_water_days == 0:
            bid = 0.0
        elif highest_prev >= 135:
            bid = 18.0 if hp >= 5 else 136.0
        else:
            bid = max(65.0, min(118.0, highest_prev * 0.85 + 4.0))

    if day >= 8:
        if hp <= 5:
            bid = max(bid, 130.0)
        elif hp >= 8 and no_water_days == 0 and slots == 1:
            bid = min(bid, 20.0)

    if urgent_opponents >= 2 and slots == 1 and hp >= 7 and no_water_days == 0:
        bid = min(bid, 12.0)

    bid = max(0.0, min(float(bid), float(budget)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opponents = []
    for o in opponents_status.values():
        if o.get('alive', True):
            alive_opponents.append(o)

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace (only immediate reaction)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate likely competitive level
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
        # If others bid high, we slightly overtake; otherwise bid near the likely clearing band.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            base = max(second_prev_bid * 1.02, DAILY_SALARY * 0.65)
        else:
            base = max(second_prev_bid * 0.95, DAILY_SALARY * 0.55)
    else:
        base = DAILY_SALARY * 0.55

    # Supply pressure: lower supply means higher chance of losing.
    # Use thresholds around given range [15,25].
    if supply <= (MIN_SUPPLY + 2):
        base *= 1.15
    elif supply >= (MAX_SUPPLY - 2):
        base *= 0.95

    # Own urgency: if low hp or accumulating no-water days, increase bid.
    if hp <= 2:
        base *= 1.35
    elif hp <= 4:
        base *= 1.20

    if no_water_days >= 2:
        base *= 1.15

    # Keep bids within a reasonable fraction of budget.
    cap = budget
    # Also avoid overcommitting: target around 0.9*salary max unless hp is critical.
    if hp > 2:
        cap = min(cap, DAILY_SALARY * 0.95)
    else:
        cap = min(cap, DAILY_SALARY * 1.1)

    bid = min(cap, base)

    # Ensure non-negative and at least a small amount if we can.
    if bid < 0:
        bid = 0
    if bid == 0 and budget > 0:
        bid = min(budget, DAILY_SALARY * 0.25)

    return float(bid)

